import time


def convert_time_format(ori_time, ori_time_format="%Y-%m-%d %H:%M:%S", dst_time_format="%a %b  %d %H:%M:%S %Z %Y"):
    """
    Covert time str to appoint format

    :param ori_time: original time
    :param ori_time_format: original time format
    :param dst_time_format: destination time format
    :return
    if raise exception,return ori_time
    else return time after convert
    """
    try:
        return time.strftime(ori_time_format, time.strptime(ori_time, dst_time_format))
    except Exception:
        return ori_time
